hooks.command:
python3 -c 'import sys, json, os, re, shlex
try:
    cmd = json.loads(sys.stdin.read()).get("tool_input", {}).get("command", "")
except Exception:
    sys.stderr.write("BLOCKED: unparseable tool input\n")
    sys.exit(2)
home = os.environ.get("HOME", "")
roots = set(["/", "~", "$HOME", "${HOME}", "/*", "~/"])
if home:
    roots.add(home)
    roots.add(home + "/")
for sub in re.split(r"&&|\|\||[;&|\n]", cmd):
    try:
        parts = shlex.split(sub)
    except Exception:
        parts = sub.split()
    while parts and ("=" in parts[0]) and not parts[0].startswith("-"):
        parts = parts[1:]
    if parts and parts[0] == "sudo":
        parts = parts[1:]
    if not parts:
        continue
    prog, args = parts[0], parts[1:]
    sf = "".join(a[1:] for a in args if re.match(r"^-[A-Za-z]", a) and not a.startswith("--"))
    lf = [a for a in args if a.startswith("--")]
    ops = [a for a in args if not a.startswith("-")]
    if prog == "rm" and ("r" in sf or "R" in sf or "--recursive" in lf) and ("f" in sf or "--force" in lf) and any(o in roots for o in ops):
        sys.stderr.write("BLOCKED: rm -rf on root/home is not allowed\n"); sys.exit(2)
    if prog == "git" and "push" in args and ("f" in sf or any(a.startswith("--force") for a in lf)):
        sys.stderr.write("BLOCKED: force push is not allowed\n"); sys.exit(2)
    if prog == "git" and "reset" in args and "--hard" in args:
        sys.stderr.write("BLOCKED: git reset --hard is not allowed\n"); sys.exit(2)
    if prog == "git" and "clean" in args and ("f" in sf or "--force" in lf):
        sys.stderr.write("BLOCKED: destructive git clean is not allowed\n"); sys.exit(2)
    if prog in ("npm", "yarn", "pnpm") and "publish" in args:
        sys.stderr.write("BLOCKED: publishing packages is not allowed\n"); sys.exit(2)
sys.exit(0)'
